[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$cases=@('PORTABLE_PAGE_METADATA','PORTABLE_TIMELINE_RANGE','PORTABLE_COST_MISMATCH','PORTABLE_HYPERCARE_EXIT','PORTABLE_OFFER_VERSIONS_MINITEMS');foreach($code in $cases){$d=Join-Path ([IO.Path]::GetTempPath()) ('portable-neg-'+[guid]::NewGuid().ToString('N'));try{& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation/New-PortableProjectStoryFixture.ps1') -Destination $d|Out-Null;$x=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json;switch($code){'PORTABLE_PAGE_METADATA'{$x.pages[0].version=2};'PORTABLE_TIMELINE_RANGE'{$x.timeline[0].time='2020-01-01T00:00:00Z'};'PORTABLE_COST_MISMATCH'{$x.offer.actual_cost=1};'PORTABLE_HYPERCARE_EXIT'{$x.hypercare[0].status='open'};'PORTABLE_OFFER_VERSIONS_MINITEMS'{$x.offer.versions=@(1)}};$x|ConvertTo-Json -Depth 30|Set-Content (Join-Path $d 'project-story.json');$out=& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation/Test-PortableProjectStoryConformance.ps1') -Path $d 2>&1|Out-String;if($LASTEXITCODE -eq 0 -or $out -notmatch $code){throw "PORTABLE_NEGATIVE_EXPECTED_$code"};Write-Host "PASS: $code"}finally{if(Test-Path $d){Remove-Item $d -Recurse -Force -ErrorAction SilentlyContinue}}}
